(1378, NULL, 'CONSTELLATION', 'BRAVA STAR NS45', 'Aeroporto de Jacarepaguá', '{"grupo":"CONSTELLATION","unidade":"BRAVA STAR NS45","data":"2026-09-29","local":"Aeroporto de Jacarepaguá","modal":"Helicóptero","preposto":"Elisa Martins","observacao_nome_arquivo":"","horarios":{"saida_hotel":[{"label1":"Previsto","h1":"10","m1":"45","label2":"Real","h2":"10","m2":"48"}],"embarque_previsto":"13:10","embarque_real":"12:58","atendimento_inicio":"10:30","atendimento_fim":"15:55"},"info_troca":"<div><span style=\"font-size: 1rem; -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">- Troca de turma concluída conforme programado.&nbsp;<\/span><\/div>","pax_embarcando":"Constellation: \n1. ALAN KARDEC DA SILVA PONTES\n2. DINIZ PAZ NETO\n3. GUSTAVO MARQUES SANTORO\n4. JORGE MORAIS ALEXANDRE JUNIOR\n5. LEANDRO CORREA SENA DA SILVA\n6. MARCELO CARDOSO DA SILVA\n7. MATEUS VIANA DA SILVA POSES\n8. PAULO CEZAR OLIVEIRA DOS SANTOS\n9. ROBERTO PINTO ROSARIO\n10. SIDICLEI DE SANTANA\n11. VAGNER FERREIRA CARDOSO ","pax_desembarcando":"Constellation: \n1. DEMETRIUS FERREIRA\n2. GABRIEL ROCHA VARJAO\n3. HENRIQUE REIS BARRAQUI\n4. HERBERT RAMOS DE CARVALHO\n5. JOSE EDUARDO SOARES NUNES\n6. LUCAS RICHA OLIVEIRA\n7. LUKA CIRIO\n8. MIGUEL GOMES MATHIAS NETTO LIMA\n9. MURILO DA SILVA FREITAS\n10. RAPHAEL DIAS LIMA ","fotos":[]}', 0, NULL, '2026-09-29 19:15:47', '2026-09-29 19:15:48', 'TECHNIP', NULL, 'relatorios_pdf/6abc0e64c91c0_BRAVA_STAR_NS45_29-09-2026_(13h10).pdf', '2804:14d:5c8c:b93e:d81e:1c63:4144:84db');
